  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    id_to_node = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    root_id = None
    for n in nodes:
        if n['parent'] is None:
            root_id = n['id']
        else:
            children.setdefault(n['parent'], []).append(n['id'])
    descendants = {}
    def dfs(node_id):
        if node_id in descendants:
            return descendants[node_id]
        sub = {node_id}
        for child in children.get(node_id, []):
            sub.update(dfs(child))
        descendants[node_id] = sub
        return sub
    for n in nodes:
        dfs(n['id'])
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    retained_ids = set(id_to_node.keys())
    removed_ids = []
    for node in sorted_nodes:
        nid = node['id']
        if nid not in retained_ids:
            continue
        if not node['removable']:
            continue
        if node['symbol'] in required_symbols:
            continue
        if nid == root_id:
            continue
        child_ids = children.get(nid, [])
        if any(cid in retained_ids for cid in child_ids):
            continue
        sub = descendants[nid]
        if any(id_to_node[sub_id]['symbol'] in required_symbols for sub_id in sub):
            continue
        retained_ids.difference_update(sub)
        removed_ids.append(nid)
    retained_ids_sorted = sorted(retained_ids)
    return {'removed_node_ids': removed_ids, 'retained_node_ids': retained_ids_sorted}
